	public static bool TryGet(string language, string key, out string value)
	{
		int index = Array.IndexOf(Languages, language);
		if (index >= 0 && Values.TryGetValue(key, out string[]? translated) && index < translated.Length && !string.IsNullOrWhiteSpace(translated[index]))
		{
			value = translated[index]; return true;
		}
		value = key; return false;
	}
